263	// TestBatchDeleteDeterministic: the same semantics with different record order
264	// produces byte-identical graph and report output.
265	func TestBatchDeleteDeterministic(t *testing.T) {
266		build := func() map[string]*Lineage {
267			return buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
268		}
269		plan1 := Plan{
270			Changes:  []PlanChange{change("D"), change("B", "D")},
271			Removals: []string{"A"},
272		}
273		plan2 := Plan{
274			Changes:  []PlanChange{change("B", "D"), change("D")},
275			Removals: []string{"A"},
276		}
277		g1 := build()
278		r1, err := ApplyBatch(g1, plan1)
279		if err != nil {
280			t.Fatalf("ApplyBatch plan1 unexpected error: %v", err)
281		}
282		g2 := build()
283		r2, err := ApplyBatch(g2, plan2)
284		if err != nil {
285			t.Fatalf("ApplyBatch plan2 unexpected error: %v", err)
286		}
287		b1, err := MarshalGraphFile(g1)
288		if err != nil {
289			t.Fatalf("MarshalGraphFile g1 unexpected error: %v", err)
290		}
291		b2, err := MarshalGraphFile(g2)
292		if err != nil {
293			t.Fatalf("MarshalGraphFile g2 unexpected error: %v", err)
294		}
295		if string(b1) != string(b2) {
296			t.Fatalf("graph bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", b1, b2)
297		}
298		rb1, err := json.Marshal(r1)
299		if err != nil {
300			t.Fatalf("json.Marshal r1 unexpected error: %v", err)
301		}
302		rb2, err := json.Marshal(r2)
303		if err != nil {
304			t.Fatalf("json.Marshal r2 unexpected error: %v", err)
305		}
306		if string(rb1) != string(rb2) {
307			t.Fatalf("report bytes differ:\n--- plan1 ---\n%s\n--- plan2 ---\n%s", rb1, rb2)
308		}
309	}
