311	// TestBatchDeletePreviewApplyConsistency: preview and apply produce the same
312	// report for the same graph and plan with removals.
313	func TestBatchDeletePreviewApplyConsistency(t *testing.T) {
314		graph := buildGraph(t, P("A"), P("B", "A"), P("C", "B"))
315		plan := Plan{
316			Changes:  []PlanChange{change("D"), change("B", "D")},
317			Removals: []string{"A"},
318		}
319		preview, err := PreviewBatch(graph, plan)
320		if err != nil {
321			t.Fatalf("PreviewBatch unexpected error: %v", err)
322		}
323		applied, err := ApplyBatch(graph, plan)
324		if err != nil {
325			t.Fatalf("ApplyBatch unexpected error: %v", err)
326		}
327		if !reflect.DeepEqual(preview, applied) {
328			t.Fatalf("preview and apply reports differ:\n preview=%#v\n applied=%#v", preview, applied)
329		}
330	}
331	
332	// TestBatchDeleteEmptyPlanAndRemovals: an empty plan and an empty removals
333	// array both succeed with empty lists.
334	func TestBatchDeleteEmptyPlanAndRemovals(t *testing.T) {
335		graph := buildGraph(t, P("A"), P("B", "A"))
336		for _, plan := range []Plan{
337			{},
338			{Removals: []string{}},
339			{Changes: []PlanChange{}, Removals: []string{}},
340		} {
341			report, err := PreviewBatch(graph, plan)
342			if err != nil {
343				t.Fatalf("PreviewBatch %+v unexpected error: %v", plan, err)
344			}
345			if len(report.RemovedDatasets) != 0 || len(report.NewDatasets) != 0 ||
346				len(report.ChangedDatasets) != 0 || len(report.AddedRelations) != 0 ||
347				len(report.RemovedRelations) != 0 || len(report.AffectedDownstreams) != 0 {
348				t.Errorf("plan %+v produced non-empty diff: %+v", plan, report)
349			}
350		}
351	}
