328		t.Run("empty name", func(t *testing.T) {
329			graph := map[string]*Lineage{"": {Dataset: ""}}
330			_, err := PreviewBatch(graph, empty)
331			if !errors.Is(err, ErrInvalidArgument) {
332				t.Fatalf("err = %v, want ErrInvalidArgument", err)
333			}
334		})
335	
336		t.Run("missing upstream", func(t *testing.T) {
337			graph := map[string]*Lineage{"A": {Dataset: "A", Parents: []string{"ghost"}}}
338			_, err := PreviewBatch(graph, empty)
339			if !errors.Is(err, ErrNotFound) {
340				t.Fatalf("err = %v, want ErrNotFound", err)
341			}
342		})
343	
344		t.Run("cycle", func(t *testing.T) {
345			graph := map[string]*Lineage{
346				"A": {Dataset: "A", Parents: []string{"B"}},
347				"B": {Dataset: "B", Parents: []string{"A"}},
348			}
349			_, err := PreviewBatch(graph, empty)
350			if !errors.Is(err, ErrCycle) {
351				t.Fatalf("err = %v, want ErrCycle", err)
352			}
353		})
354	}
