356	// TestBatchEmptyGraphAllowsNewDatasets verifies that an empty graph accepts a
357	// batch that registers new datasets.
358	func TestBatchEmptyGraphAllowsNewDatasets(t *testing.T) {
359		graph := map[string]*Lineage{}
360		plan := planOf(change("A"), change("B", "A"))
361		report, err := PreviewBatch(graph, plan)
362		if err != nil {
363			t.Fatalf("PreviewBatch unexpected error: %v", err)
364		}
365		wantNew := []string{"A", "B"}
366		if !reflect.DeepEqual(report.NewDatasets, wantNew) {
367			t.Errorf("NewDatasets = %v, want %v", report.NewDatasets, wantNew)
368		}
369		if len(report.ChangedDatasets) != 0 {
370			t.Errorf("ChangedDatasets = %v, want empty", report.ChangedDatasets)
371		}
372		if _, err := ApplyBatch(graph, plan); err != nil {
373			t.Fatalf("ApplyBatch unexpected error: %v", err)
374		}
375		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"A"}) {
376			t.Errorf("Roots = %v, want [A]", roots)
377		}
378	}
