380	// TestBatchPreservesNames verifies that name casing and spaces are preserved.
381	func TestBatchPreservesNames(t *testing.T) {
382		graph := map[string]*Lineage{}
383		plan := planOf(change(" Raw-Blocks "), change("RAW-BLOCKS", " Raw-Blocks "))
384		if _, err := ApplyBatch(graph, plan); err != nil {
385			t.Fatalf("ApplyBatch unexpected error: %v", err)
386		}
387		if got := graph["RAW-BLOCKS"].Parents; !reflect.DeepEqual(got, []string{" Raw-Blocks "}) {
388			t.Fatalf("name was trimmed or case-folded: %v", got)
389		}
